class Solution {
public:
    string nextClosestTime(string time) {
        bool allowed[10] = {};
        for (char c : time) {
            if (c != ':') {
                allowed[c - '0'] = true;
            }
        }
        int start = stoi(time.substr(0, 2)) * 60 + stoi(time.substr(3, 2));
        for (int delta = 1; delta <= 1440; ++delta) {
            int minute = (start + delta) % 1440;
            int hour = minute / 60;
            int rem = minute % 60;
            string result = string(2 - to_string(hour).size(), '0')
                          + to_string(hour) + ":"
                          + string(2 - to_string(rem).size(), '0')
                          + to_string(rem);
            bool valid = true;
            for (char c : result) {
                if (c != ':' && !allowed[c - '0']) {
                    valid = false;
                }
            }
            if (valid) {
                return result;
            }
        }
        return time;
    }
};
